1	/** Receipt gate for named-worktree merges: a recorded passing verification for the exact state, or an explicit recorded waiver. */
2	import { test } from "node:test";
3	import assert from "node:assert/strict";
4	import fs from "node:fs";
5	import os from "node:os";
6	import path from "node:path";
7	import { execFileSync } from "node:child_process";
8	import { runWorktreeCommand } from "../src/worktrunk/command.js";
9	import { recordVerification, captureVerificationState, recordVerificationIfEligible } from "../src/worktrunk/verification.js";
10	import { readRegistry, writeRegistry } from "../src/worktrunk/registry.js";
11	
12	function git(cwd: string, ...args: string[]): string {
13	  return execFileSync("git", args, { cwd, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }).trim();
14	}
15	
16	function fixture() {
17	  const root = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), "nexus-wtreceipt-")));
18	  const repo = path.join(root, "proj");
19	  const home = path.join(root, "home");
20	  fs.mkdirSync(repo);
21	  fs.mkdirSync(home);
22	  git(repo, "init", "-q", "-b", "main");
23	  git(repo, "config", "user.email", "t@example.com");
24	  git(repo, "config", "user.name", "T");
25	  git(repo, "config", "commit.gpgsign", "false");
26	  fs.writeFileSync(path.join(repo, "a.txt"), "one\n");
27	  git(repo, "add", ".");
28	  git(repo, "commit", "-q", "-m", "init");
29	  const wt = (cwd: string, args: string[]) => runWorktreeCommand(args, { cwd, home, readOnly: false });
30	  const made = wt(repo, ["switch", "-c", "feat/r", "--no-copy"]);
31	  assert.equal(made.success, true, made.output);
32	  const dir = path.join(repo, ".nexus", "worktrees", "feat-r");
33	  fs.writeFileSync(path.join(dir, "b.txt"), "b\n");
34	  git(dir, "add", "b.txt");
35	  git(dir, "commit", "-q", "-m", "add b");
36	  return { root, repo, home, dir, wt, cleanup: () => fs.rmSync(root, { recursive: true, force: true }) };
37	}
38	
39	test("merge without a recorded verification or a waiver is refused and changes nothing", () => {
40	  const f = fixture();
41	  try {
42	    const before = git(f.repo, "rev-parse", "HEAD");
43	    const r = f.wt(f.dir, ["merge"]);
44	    assert.equal(r.success, false);
45	    assert.match(r.output, /verification|receipt/i);
46	    assert.match(r.output, /--no-verify-receipt/);
47	    assert.equal(git(f.repo, "rev-parse", "HEAD"), before);
48	    assert.ok(fs.existsSync(f.dir));
49	    assert.equal(git(f.repo, "for-each-ref", "refs/nexus-backup"), "");
50	  } finally { f.cleanup(); }
51	});
52	
53	test("a recorded passing verification for the exact head lets the merge through", () => {
54	  const f = fixture();
55	  try {
56	    assert.equal(recordVerification(f.dir, "npm test"), true);
57	    const reg = readRegistry(path.join(f.repo, ".git")).registry;
58	    assert.equal(reg.verifications?.[0].branch, "feat/r");
59	    assert.equal(reg.verifications?.[0].head, git(f.dir, "rev-parse", "HEAD"));
60	    const r = f.wt(f.dir, ["merge"]);
61	    assert.equal(r.success, true, r.output);
62	    assert.ok(fs.existsSync(path.join(f.repo, "b.txt")));
63	  } finally { f.cleanup(); }
64	});
65	
66	test("a verification does not cover a later commit or later uncommitted edits", () => {
67	  const f = fixture();
68	  try {
69	    recordVerification(f.dir, "npm test");
70	    fs.writeFileSync(path.join(f.dir, "c.txt"), "c\n");
71	    git(f.dir, "add", "c.txt");
72	    git(f.dir, "commit", "-q", "-m", "add c");
73	    assert.equal(f.wt(f.dir, ["merge"]).success, false);
74	    recordVerification(f.dir, "npm test");
75	    fs.writeFileSync(path.join(f.dir, "d.txt"), "unverified\n");
76	    const r = f.wt(f.dir, ["merge"]);
77	    assert.equal(r.success, false);
78	    assert.equal(fs.existsSync(path.join(f.repo, "c.txt")), false);
79	  } finally { f.cleanup(); }
